/**
 * SetupQueryStore — auto-generated by .tmp_gen_stores.mjs.
 *
 * Thin store wrapping the Query-side Repository singletons for this feature.
 * Every action delegates to `repo.<method>(...)` inside a try/finally that
 * toggles per-method loading/error state. Follows the §5.4 R5.1 double-export
 * pattern so tests can inject a mock repo via `createSetupQueryStore(mock)`.
 *
 * When a feature needs custom orchestration (multi-repo transactions,
 * derived state, cache invalidation) — replace this generated file with a
 * hand-written store; the generator will skip files it did not create.
 */

import { defineStore } from 'pinia'
import { reactive } from 'vue'
import type { SetupRepository } from '@/features/setup/domain/repositories/setupRepository'
import { setupRepository as default_setup_repo } from '@/features/setup/data/repositories/setupRepositoryImpl'

export function createSetupQueryStore(setupRepo: SetupRepository = default_setup_repo) {
  return defineStore('setup/query', () => {
    const loading = reactive<Record<string, boolean>>({ getSetupStatus: false })
    const errors = reactive<Record<string, unknown>>({ getSetupStatus: null as unknown })

  const getSetupStatus: SetupRepository['getSetupStatus'] = ((...args: unknown[]) => {
    loading.getSetupStatus = true
    errors.getSetupStatus = null
    return Promise.resolve()
      .then(() => (setupRepo.getSetupStatus as (...a: unknown[]) => unknown)(...args))
      .catch((error: unknown) => { errors.getSetupStatus = error; throw error })
      .finally(() => { loading.getSetupStatus = false })
  }) as SetupRepository['getSetupStatus']

    return { loading, errors, getSetupStatus }
  })
}

export const useSetupQueryStore = createSetupQueryStore()
